package com.foodbridge.payment;
import com.foodbridge.orders.*;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;
@Controller public class PaymentController {private final PurchaseOrderRepository orders;private final OrderService service;private final PaymentTransactionRepository payments;public PaymentController(PurchaseOrderRepository o,OrderService s,PaymentTransactionRepository p){orders=o;service=s;payments=p;}
    @GetMapping("/payments/demo/{id}") public String checkout(@PathVariable Long id,Authentication auth,Model m){PurchaseOrder o=orders.findById(id).orElseThrow();if(!o.getConsumerEmail().equalsIgnoreCase(auth.getName()))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN);m.addAttribute("order",o);m.addAttribute("payment",payments.findFirstByOrderIdOrderByIdDesc(id).orElseThrow());return "payment/demo-checkout";}
    @PostMapping("/payments/demo/{id}/result") public String result(@PathVariable Long id,@RequestParam boolean success,Authentication auth){try{PurchaseOrder o=service.completeDemoPayment(id,auth.getName(),success);return "redirect:/orders/"+o.getId();}catch(RuntimeException e){return "redirect:/consumer/orders?error";}}
    @GetMapping("/orders/{id}") public String detail(@PathVariable Long id,Authentication auth,Model m){PurchaseOrder o=orders.findById(id).orElseThrow();if(!o.getConsumerEmail().equalsIgnoreCase(auth.getName()))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN);m.addAttribute("order",o);return "orders/detail";}
}
